// ── Keeping the till on screen when the line drops ────────────────────────────
// Hand-written rather than generated by a PWA plugin, for two reasons: Serwist
// forces the whole production build back onto webpack (see the Next PWA guide),
// and it writes this file, which would silently delete the push handler below.
//
// Only /seller is cached. Admin and the QR menu deliberately stay online-only —
// stale reports and a menu edited against a stale copy are worse than an error.

const CACHE = 'possiblle-till-v1';

self.addEventListener('install', e => e.waitUntil(self.skipWaiting()));

self.addEventListener('activate', e =>
  e.waitUntil((async () => {
    // A rename of CACHE above is how a bad cache gets abandoned on next deploy.
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })()),
);

// The till's own reference data. Fine to serve a few minutes stale — a menu
// price from this morning beats a blank screen — but always refreshed behind
// the answer so the next order sees the new one.
const CACHEABLE_API = /^\/api\/public-(menu|categories|tables|staff|modifiers|stations)(\?|$)/;

async function staleWhileRevalidate(req) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(req);
  const fresh = fetch(req)
    .then(res => {
      if (res.ok) cache.put(req, res.clone());
      return res;
    })
    .catch(() => null);
  if (cached) {
    void fresh; // refresh in the background, answer now
    return cached;
  }
  return (await fresh) ?? Response.error();
}

async function networkFirst(req) {
  const cache = await caches.open(CACHE);
  try {
    const res = await fetch(req);
    if (res.ok) cache.put(req, res.clone());
    return res;
  } catch {
    const cached = await cache.match(req);
    if (cached) return cached;
    throw new Error('offline and not cached');
  }
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return; // writes are queued in the page, not here

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Hashed filenames never change contents — cache first, forever.
  if (url.pathname.startsWith('/_next/static/')) {
    e.respondWith(
      caches.open(CACHE).then(async cache => {
        const hit = await cache.match(req);
        if (hit) return hit;
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      }),
    );
    return;
  }

  if (CACHEABLE_API.test(url.pathname + url.search)) {
    e.respondWith(staleWhileRevalidate(req));
    return;
  }

  // The till itself, so a reload — or a cold start after a power cut, which is
  // the same thing to the browser — still opens. Both addresses it is served
  // from: /seller for a signed-in waiter, /s/<slug>/<token> for the public
  // terminal the desktop app runs.
  //
  // Deliberately not the admin or QR pages: those stay online-only, and caching
  // their shell would only let someone open a screen that cannot load its data.
  if (req.mode === 'navigate' && (url.pathname.startsWith('/seller') || url.pathname.startsWith('/s/'))) {
    e.respondWith(networkFirst(req));
    return;
  }
});

// ── Web Push ──────────────────────────────────────────────────────────────────
// A page cannot make a sound once its tab is hidden or the phone is locked — the
// browser suspends it. So the "order ready" alert for a backgrounded waiter arrives
// here instead, as an OS notification the service worker shows even while the app is
// closed. Sent by app/api/notify-ready; subscribed from the seller screen.
self.addEventListener('push', e => {
  let data = {};
  try { data = e.data ? e.data.json() : {}; } catch { /* non-JSON payload */ }
  const title = data.title || 'Sifariş hazırdır';
  const options = {
    body: data.body || 'Bir sex sifarişi hazır etdi',
    icon: data.icon || '/icon-192.png',
    badge: data.badge || '/icon-192.png',
    vibrate: [200, 100, 200],
    // Same order collapses onto one notification instead of stacking; renotify still
    // buzzes so a second sex finishing is not silently swallowed.
    tag: data.tag || 'order-ready',
    renotify: true,
    data: { url: data.url || '/seller' },
  };
  e.waitUntil(self.registration.showNotification(title, options));
});

// Tapping the notification focuses an already-open waiter tab if there is one, else
// opens a fresh one — never a duplicate.
self.addEventListener('notificationclick', e => {
  e.notification.close();
  const url = (e.notification.data && e.notification.data.url) || '/seller';
  e.waitUntil((async () => {
    const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const c of clients) {
      if (c.url.includes('/seller') && 'focus' in c) return c.focus();
    }
    if (self.clients.openWindow) return self.clients.openWindow(url);
  })());
});
